// Turn each CRM event into a WhatsApp message.
// Returning no item for a type means "nothing to send" — the event is still
// acknowledged below so it does not come round again.

const out = [];

for (const item of $input.all()) {
  const e = item.json;
  const d = e.data ?? {};
  const to = d.whatsappNumber ?? d.customer?.whatsappNumber;
  const order = d.orderNumber ?? '';
  const name = (d.customerName ?? d.customer?.name ?? '').split(' ')[0];
  const hi = name ? `Hi ${name}, ` : '';

  let text = null;

  switch (e.type) {
    case 'ORDER_CONFIRMED':
      text = `${hi}your order ${order} is confirmed. Total ₹${d.totalAmount}. We'll let you know when it's ready!`;
      break;
    case 'PAYMENT_FAILED':
      text = `${hi}your payment for ${order} didn't go through${d.failureReason ? ` (${d.failureReason})` : ''}. Reply RETRY to try again.`;
      break;
    case 'ORDER_READY':
      text = `${hi}your order ${order} is ready.`;
      break;
    case 'ORDER_OUT_FOR_DELIVERY':
      text = `${hi}your order ${order} is on its way.`;
      break;
    case 'ORDER_DELIVERED':
      text = `${hi}your order has been delivered. Thank you for ordering! How would you rate it from 1 to 5?`;
      break;
    case 'ORDER_CANCELLED':
      text = `${hi}your order ${order} has been cancelled.`;
      break;
    default:
      text = null; // CUSTOMER_CREATED, PAYMENT_SUCCESS, REVIEW_RECEIVED — internal only
  }

  out.push({ json: { eventId: e.id, type: e.type, to, text, send: Boolean(text && to) } });
}

return out;
